// REQ-162 (docs/sims.md 9.1-9.3): criteria, the process score, the
// Good/Mediocre/Bad rating and the debrief data. Evaluated once, after the
// run, over the final state and the command log, with the scoring-only
// functions. Deterministic: the same run always scores the same.

import type { Command, CriterionResult, CriterionRowScore, CriterionScore, DebriefData, Id, OutcomeClass, Rating, ReasoningGrade, Value } from "./types.ts";
import type { Run } from "./engine.ts";
import { COMMAND_BUDGET, renderTemplate, simTimeText } from "./engine.ts";
import type { Frame, ScoringHooks } from "./eval.ts";
import { asBool, evaluate, frameWith } from "./eval.ts";
import { parseCached } from "./parser.ts";
import { applyFormat } from "./format.ts";

// Rating thresholds are engine constants, so a rating means the same thing
// in every sim (9.2).
export const GOOD_MIN_SCORE = 85;
export const BAD_MAX_SCORE = 60; // a score below this is Bad

export function rateRun(outcome: OutcomeClass | null, processScore: number | null, criticalMissed: number): Rating | null {
  if (outcome === null || processScore === null) return null;
  if (outcome === "harm" || processScore < BAD_MAX_SCORE || criticalMissed >= 2) return "bad";
  if (outcome === "target" && criticalMissed === 0 && processScore >= GOOD_MIN_SCORE) return "good";
  return "mediocre";
}

export function scoreValue(s: CriterionScore): number {
  return s === "met" ? 1 : s === "partial" ? 0.5 : 0;
}

// 100 x sum(weight x value) / sum(weight), rounded; grader_failed moments
// and "na" criteria leave both numerator and denominator (9.1).
export function processScoreOf(criteria: { weight: number; score: CriterionRowScore }[], reasoning: { weight: number; score: CriterionScore | "grader_failed" }[]): number | null {
  let num = 0;
  let den = 0;
  for (const c of criteria) {
    if (c.score === "na") continue;
    num += c.weight * scoreValue(c.score);
    den += c.weight;
  }
  for (const r of reasoning) {
    if (r.score === "grader_failed") continue;
    num += r.weight * scoreValue(r.score);
    den += r.weight;
  }
  if (den <= 0) return null;
  return Math.round((100 * num) / den);
}

function actParamsFrame(run: Run, cmd: Extract<Command, { type: "act" }>): Record<string, Value> {
  const vars: Record<string, Value> = { t: cmd.tick * run.c.dt };
  const action = run.c.doc.actions[cmd.action];
  const given = cmd.params ?? {};
  for (const p of action?.params ?? []) {
    switch (p.kind) {
      case "choice":
      case "query":
        vars[p.id] = given[p.id] ?? "";
        break;
      case "form":
        for (const f of p.fields) vars[f.id] = given[f.id] ?? "";
        break;
      case "slot":
        vars[p.id] = { id: given[p.id] ?? "", slot: given[`${p.id}.slot`] ?? "" } as Value;
        break;
      case "pick":
        vars[p.id] = { _id: typeof given[p.id] === "number" ? (given[p.id] as number) : 0 } as Value;
        break;
      case "command":
        vars[p.id] = { text: given[p.id] ?? "", matched: "" } as Value;
        break;
    }
  }
  return vars;
}

export function scoringHooks(run: Run, pausedSeconds: number): ScoringHooks {
  const cmds = run.commands;
  const dt = run.c.dt;
  return {
    firstAct(action, cond) {
      for (const c of cmds) {
        if (c.type !== "act" || c.action !== action) continue;
        if (cond) {
          const frame: Frame = frameWith(null, actParamsFrame(run, c));
          if (!cond(frame)) continue;
        }
        return c.tick * dt;
      }
      return null;
    },
    countAct(action) {
      let n = 0;
      for (const c of cmds) if (c.type === "act" && c.action === action) n++;
      return n;
    },
    actedBefore(action, seconds) {
      for (const c of cmds) if (c.type === "act" && c.action === action && c.tick * dt < seconds) return true;
      return false;
    },
    everTrue(trigger) {
      const i = run.c.doc.triggers.findIndex((t) => t.id === trigger);
      return i >= 0 && run.state.triggerFired[i];
    },
    ending: () => run.state.ended?.ending ?? "",
    outcomeClass: () => run.state.ended?.class ?? "none",
    pausedTotal: () => pausedSeconds,
    skips: () => run.skips.length,
    chose(prompt, choice) {
      for (const c of cmds) if (c.type === "choose" && c.prompt === prompt && c.choice === choice) return true;
      return false;
    },
  };
}

export interface ScoreInput {
  reasoningGrades: ReasoningGrade[]; // one per moment the server graded; missing moments count as missed
  pausedSeconds: number;
}

export function scoreRun(run: Run, input: ScoreInput): DebriefData {
  const doc = run.c.doc;
  const hooks = scoringHooks(run, input.pausedSeconds);
  const saved = run.ctx.scoring;
  run.ctx.scoring = hooks;
  run.ctx.evals = 0;
  run.ctx.budget = COMMAND_BUDGET * 4;
  run.ctx.t = run.state.tick * run.c.dt;
  try {
    const criteria: CriterionResult[] = doc.scoring.criteria.map((c) => {
      let score: CriterionRowScore = "missed";
      let why = "";
      for (const row of c.rows) {
        if (asBool(evaluate(parseCached(row.when), null, run.ctx))) {
          score = row.score;
          why = renderTemplate(run, row.why, null);
          break;
        }
      }
      return { id: c.id, label: c.label, weight: c.weight, critical: !!c.critical, score, why };
    });
    const reasoning = doc.scoring.reasoningCriteria.map((rc) => {
      const g = input.reasoningGrades.find((x) => x.moment === rc.moment);
      const score: CriterionScore | "grader_failed" = g ? g.score : "missed";
      return { moment: rc.moment, label: rc.label, weight: rc.weight, critical: !!rc.critical, score };
    });
    const ended = run.state.ended;
    const terminal = ended && (ended.reason === "ending" || ended.reason === "time_up");
    const outcome: OutcomeClass | null = terminal ? ended.class : null;
    const processScore = terminal ? processScoreOf(criteria, reasoning) : null;
    const criticalMissed = criteria.filter((c) => c.critical && c.score === "missed").length + reasoning.filter((r) => r.critical && r.score === "missed").length;
    const rating = rateRun(outcome, processScore, criticalMissed);
    const kpis = doc.scoring.kpis.map((k) => {
      const raw = evaluate(parseCached(k.value), null, run.ctx);
      const value = typeof raw === "number" || raw === null ? applyFormat(raw, k.format === "duration" ? "duration" : k.format === "usd" ? "usd" : null, run.c.base, doc.clock.calendar) : String(raw);
      return { id: k.id, label: k.label, value, raw, expert: k.expert };
    });
    const endingId: Id | null = ended?.ending ?? null;
    const ending = endingId ? doc.endings[endingId] : null;
    const debrief = endingId ? doc.scoring.debrief[endingId] : undefined;
    const timeline = run.commands.map((c) => {
      const time = simTimeText(run, c.tick);
      switch (c.type) {
        case "act": {
          const a = doc.actions[c.action];
          const params = c.params ? Object.keys(c.params).map((k) => `${k}=${String(c.params?.[k])}`).join(", ") : "";
          return { tick: c.tick, time, kind: "act" as const, text: `${a?.label ?? c.action}${params ? ` (${params})` : ""}` };
        }
        case "choose": {
          const p = (doc.prompts ?? {})[c.prompt];
          const ch = p?.choices.find((x) => x.id === c.choice);
          return { tick: c.tick, time, kind: "choose" as const, text: `${p?.title ?? c.prompt}: ${ch?.label ?? c.choice}` };
        }
        case "skip": {
          const rec = run.skips.find((s) => s.seq === c.seq);
          const label = doc.timers[c.timer]?.label ?? c.timer;
          return { tick: c.tick, time, kind: "skip" as const, text: `Skipped ahead to ${label} (${rec ? simTimeText(run, rec.to) : "?"})${rec?.stoppedBy ? `, stopped early: ${rec.stoppedBy}` : ""}` };
        }
        case "pause":
          return { tick: c.tick, time, kind: "pause" as const, text: `Paused (${c.reason})` };
        case "resume":
          return { tick: c.tick, time, kind: "resume" as const, text: "Resumed" };
        case "reason":
          return { tick: c.tick, time, kind: "reason" as const, text: c.answered ? "Reasoning submitted" : "Reasoning skipped" };
        case "end":
          return { tick: c.tick, time, kind: "end" as const, text: "Ended the run" };
      }
    });
    return {
      ending: endingId,
      endingLabel: ending?.label ?? (ended?.reason === "learner_quit" ? "Ended early" : ended?.reason === "engine_error" ? "Engine error" : ""),
      outcomeClass: outcome,
      rating,
      processScore,
      criteria,
      reasoning,
      kpis,
      headline: debrief ? debrief.headline : ending?.label ?? "",
      body: debrief ? renderTemplate(run, debrief.body, null) : ending ? renderTemplate(run, ending.narrative, null) : "",
      timeline,
      skippedTicks: run.skippedTicks,
      realtimeTicks: run.realtimeTicks,
      skips: run.skips.length,
      pausedSeconds: input.pausedSeconds,
      seed: run.seed,
      expertPath: doc.scoring.expertPath,
      modelReasoning: doc.scoring.modelReasoning,
    };
  } finally {
    run.ctx.scoring = saved;
  }
}
